(window.AtlasPacks = window.AtlasPacks || {})["ru"] = {"strings":{"{n} billion":{"one":"{n} миллиард","few":"{n} миллиарда","many":"{n} миллиардов","other":"{n} миллиарда"},"{n} million":{"one":"{n} миллион","few":"{n} миллиона","many":"{n} миллионов","other":"{n} миллиона"},"{n} thousand":{"one":"{n} тысяча","few":"{n} тысячи","many":"{n} тысяч","other":"{n} тысячи"},"Flag of {name}":"Флаг: {name}","Captain Skye":"Капитан Скай","Next":"Дальше","Whole world":"Весь мир","Which country has this flag?":"Чей это флаг?","Which flag belongs to {name}?":"Какой флаг у страны {name}?","What is the capital of {name}?":"Какая столица у страны {name}?","{city} is the capital of…":"{city} — столица страны…","Find {name}":"Найди: {name}","It is tiny: look for its dot!":"Она крошечная: ищи точку!","Tap it on the globe.":"Нажми на неё на глобусе.","Where is {city}?":"Где находится {city}?","Tap the country it is the capital of.":"Нажми на страну, столица которой этот город.","{name} is famous for…":"{name} славится…","Which country is a neighbour of {name}?":"Какая страна — сосед страны {name}?","Which language do many people speak in {name}?":"На каком языке говорят многие жители страны {name}?","Which continent is {name} in?":"На каком материке находится {name}?","Does {name} touch the sea?":"Есть ли у страны {name} выход к морю?","Yes, it has a coast":"Да, есть берег","No, it is landlocked":"Нет, моря нет","Which has more people?":"Где больше жителей?","Fly to the country with this flag":"Лети в страну с этим флагом","Fly to the country famous for {thing}":"Лети в страну, которая славится {thing}","Fly to the country whose capital is {city}":"Лети в страну, чья столица — {city}","Fly to the country next to {a} and {b}":"Лети в страну, у которой соседи — {a} и {b}","{mode} · {n} right":"{mode} · верно: {n}","Quiz: {name}":"Викторина: {name}","{mode} · {i} of {n}":"{mode} · {i} из {n}","Flag {n}":"Флаг {n}","Show me":"Покажи","{name} lights up on your map!":"{name} загорается на твоей карте!","Right! {n} in a row!":"Верно! {n} подряд!","Right!":"Верно!","Not quite. Here is the answer.":"Не совсем. Вот ответ.","Not quite: that is the flag of {name}.":"Не совсем: это флаг страны {name}.","Not quite: {city} is the capital of {name}.":"Не совсем: {city} — столица страны {name}.","Not quite: that was {name}.":"Не совсем: это {name}.","About {name}":"О стране {name}","Finish":"Готово","{name} is lit!":"{name} горит!","You lit up all of {region}! New badge in your passport.":"Весь континент горит: {region}! В паспорте новый значок.","New plane paint in your passport!":"В паспорте новая краска для самолёта!","That is {name}.":"Это {name}.","{place} is about {km} km to the {dir}.":"{place} — примерно в {km} km на {dir}.","Here it is: {name}.":"Вот она: {name}.","You got {a} of {b} right!":"Верно: {a} из {b}!","{n} in 60 seconds!":"{n} за 60 секунд!","Expedition done: {a} of {b}":"Экспедиция пройдена: {a} из {b}","{a} of {b} right!":"Верно: {a} из {b}!","{n} of 3 to light it up":"{n} из 3, чтобы зажечь","Lit!":"Горит!","Capital":"Столица","People":"Жители","Languages":"Языки","Famous for":"Чем славится","Neighbours":"Соседи","None: only the sea!":"Нет: вокруг только море!","Did you know?":"Знаешь ли ты?","Read it to me":"Прочитай вслух","Close":"Закрыть","Quiz me":"Проверь меня","Tap any country on the globe to open its file.":"Нажми на любую страну на глобусе, чтобы открыть её досье.","{n} lit":"Горит: {n}","Your passport":"Твой паспорт","{n} of {all} countries lit up.":"Зажжено стран: {n} из {all}.","Get a country right 3 times to light it up.":"Ответь верно про страну 3 раза — и она загорится.","Best speed round: {n}":"Рекорд блица: {n}","Expedition streak: {n} days":{"one":"Экспедиции подряд: {n} день","few":"Экспедиции подряд: {n} дня","many":"Экспедиции подряд: {n} дней","other":"Экспедиции подряд: {n} дня"},"Plane paint":"Краска для самолёта","Stamps":"Штампы","Continents":"Материки","Done":"Готово","Atlas Quest settings":"Настройки Atlas Quest","Start over":"Начать заново","Clears your lit countries, stamps and paint":"Стирает зажжённые страны, штампы и краски","Start over?":"Начать заново?","Your map goes back to grey. This cannot be undone.":"Карта снова станет серой. Отменить это нельзя.","Keep my map":"Оставить карту","Yes, start over":"Да, заново","A fresh grey map. Off you go!":"Новая серая карта. Вперёд!","Sound and more":"Звук и другое","{n} of {all} countries lit up":"Зажжено стран: {n} из {all}","Where to, pilot?":"Куда летим, пилот?","{n} countries lit up. Keep going!":{"one":"{n} страна горит. Так держать!","few":"{n} страны горят. Так держать!","many":"{n} стран горят. Так держать!","other":"{n} страны горят. Так держать!"},"Light up the world: get a country right 3 times to colour it in.":"Зажги весь мир: ответь верно про страну 3 раза, чтобы раскрасить её.","Easy: famous countries":"Легко: известные страны","Explorer: every country":"Исследователь: все страны","Done today! Streak: {n}":"На сегодня всё! Серия: {n}","Best: {n}":"Рекорд: {n}","Drag to spin the globe, pinch to zoom, tap a country to read its file.":"Тяни, чтобы крутить глобус, своди пальцы для масштаба, нажми на страну, чтобы открыть её досье.","Fly round the world and light up every country!":"Облети весь мир и зажги каждую страну!","Welcome aboard, pilot! I am Captain Skye. The world map has gone all grey, and we need a sharp-eyed explorer to colour it back in.":"Добро пожаловать на борт, пилот! Я капитан Скай. Карта мира стала совсем серой, и нам нужен зоркий исследователь, чтобы снова её раскрасить.","Let's fly!":"Полетели!","Title screen":"Главный экран","Settings":"Настройки","Back":"Назад","Africa":"Африка","Asia":"Азия","Europe":"Европа","North America":"Северная Америка","South America":"Южная Америка","Oceania":"Океания","Find it":"Найди страну","Tap countries on the globe":"Нажимай на страны на глобусе","Flag match":"Флаги","Flags and their countries":"Флаги и их страны","Capital hop":"Столицы","Capital cities":"Главные города стран","Daily expedition":"Экспедиция дня","A new route every day":"Каждый день новый маршрут","Speed round":"Блиц","60 seconds, go!":"60 секунд, вперёд!","Country files":"Досье стран","Sky blue":"Небесно-голубой","Coral red":"Коралловый","Mint green":"Мятный","Grape purple":"Виноградный","Sunny yellow":"Солнечно-жёлтый","Peach":"Персиковый","Cocoa":"Какао","Snow white":"Белоснежный","north":"север","north-east":"северо-восток","east":"восток","south-east":"юго-восток","south":"юг","south-west":"юго-запад","west":"запад","north-west":"северо-запад","Dari":"дари","Pashto":"пушту","Portuguese":"португальский","Umbundu":"умбунду","Kimbundu":"кимбунду","Albanian":"албанский","Catalan":"каталанский","Spanish":"испанский","Arabic":"арабский","English":"английский","Armenian":"армянский","German":"немецкий","Azerbaijani":"азербайджанский","Russian":"русский","Kirundi":"кирунди","French":"французский","Dutch":"нидерландский","Fon":"фон","Yoruba":"йоруба","Moore":"мооре","Dyula":"дьюла","Bengali":"бенгальский","Bulgarian":"болгарский","Bosnian":"боснийский","Croatian":"хорватский","Serbian":"сербский","Belarusian":"белорусский","Belizean Creole":"белизский креольский","Quechua":"кечуа","Aymara":"аймара","Malay":"малайский","Dzongkha":"дзонг-кэ","Tswana":"тсвана","Sango":"санго","Italian":"итальянский","Chinese":"китайский","Baoule":"бауле","Lingala":"лингала","Swahili":"суахили","Kituba":"китуба","Comorian":"коморский","Cape Verdean Creole":"кабувердьяну","Greek":"греческий","Turkish":"турецкий","Czech":"чешский","Somali":"сомалийский","Danish":"датский","Berber":"берберский","Tigrinya":"тигринья","Estonian":"эстонский","Amharic":"амхарский","Oromo":"оромо","Finnish":"финский","Swedish":"шведский","Fijian":"фиджийский","Fiji Hindi":"фиджийский хинди","Chuukese":"чуукский","Pohnpeian":"понпейский","Fang":"фанг","Georgian":"грузинский","Twi":"чви","Ewe":"эве","Fula":"фула","Maninka":"манинка","Mandinka":"мандинка","Wolof":"волоф","Kriol":"гвинейский креольский","Haitian Creole":"гаитянский креольский","Hungarian":"венгерский","Indonesian":"индонезийский","Hindi":"хинди","Irish":"ирландский","Persian":"персидский","Kurdish":"курдский","Icelandic":"исландский","Hebrew":"иврит","Jamaican Patois":"ямайский креольский","Japanese":"японский","Kazakh":"казахский","Kyrgyz":"киргизский","Khmer":"кхмерский","Gilbertese":"кирибатский","Korean":"корейский","Lao":"лаосский","Sinhala":"сингальский","Tamil":"тамильский","Sotho":"сесото","Lithuanian":"литовский","Luxembourgish":"люксембургский","Latvian":"латышский","Romanian":"румынский","Malagasy":"малагасийский","Dhivehi":"мальдивский","Marshallese":"маршалльский","Macedonian":"македонский","Bambara":"бамбара","Maltese":"мальтийский","Burmese":"бирманский","Montenegrin":"черногорский","Mongolian":"монгольский","Makhuwa":"макуа","Tsonga":"тсонга","Mauritian Creole":"маврикийский креольский","Chewa":"чева","Oshiwambo":"ошивамбо","Afrikaans":"африкаанс","Hausa":"хауса","Zarma":"зарма","Norwegian":"норвежский","Sami":"саамский","Nepali":"непальский","Nauruan":"науруанский","Māori":"маори","Urdu":"урду","Punjabi":"панджаби","Filipino":"филиппинский","Palauan":"палауский","Tok Pisin":"ток-писин","Hiri Motu":"хири-моту","Polish":"польский","Guaraní":"гуарани","Kinyarwanda":"киньяруанда","Pijin":"пиджин","Krio":"крио","Dinka":"динка","Forro":"форро","Sranan Tongo":"сранан-тонго","Slovak":"словацкий","Slovene":"словенский","Swazi":"свази","Seychellois Creole":"сейшельский креольский","Kabiye":"кабье","Thai":"тайский","Tajik":"таджикский","Turkmen":"туркменский","Tetum":"тетум","Tongan":"тонганский","Tuvaluan":"тувалу","Luganda":"луганда","Ukrainian":"украинский","Uzbek":"узбекский","Latin":"латынь","Vietnamese":"вьетнамский","Bislama":"бислама","Samoan":"самоанский","Zulu":"зулу","Xhosa":"коса","Bemba":"бемба","Nyanja":"ньянджа","Shona":"шона","Ndebele":"ндебеле","name.AF":"Афганистан","cap.AF":"Кабул","fam.AF":"синими камнями лазуритами","fact.AF":"Озёра Банди-Амир в Афганистане ярко-синие. Их удерживают природные стены из минералов, словно каменные плотины, построенные самой природой.","name.AO":"Ангола","cap.AO":"Луанда","fam.AO":"гигантской чёрной антилопой","fact.AO":"Водопад Каландула — один из самых больших в Африке: высотой больше 100 метров и шириной около 400 метров.","name.AL":"Албания","cap.AL":"Тирана","fam.AL":"источником Синий глаз","fact.AL":"В Албании многие кивают головой, когда говорят «нет», и качают ею, когда говорят «да», — наоборот, чем в большинстве стран!","name.AD":"Андорра","cap.AD":"Андорра-ла-Велья","fam.AD":"двумя соправителями","fact.AD":"В Андорре нет ни аэропорта, ни железной дороги, поэтому все гости приезжают по дорогам через высокие Пиренейские горы.","name.AE":"Объединённые Арабские Эмираты","cap.AE":"Абу-Даби","fam.AE":"небоскрёбом Бурдж-Халифа","fact.AE":"В ОАЭ есть огромный крытый горнолыжный склон с настоящим снегом и даже пингвинами — прямо посреди жаркой пустынной страны.","name.AR":"Аргентина","cap.AR":"Буэнос-Айрес","fam.AR":"ледником Перито-Морено","fact.AR":"Один из самых больших динозавров, которых когда-либо находили, — травоядный ящер длиной больше 30 метров — был откопан в Патагонии на юге Аргентины.","name.AM":"Армения","cap.AM":"Ереван","fam.AM":"абрикосами и горой Арарат","fact.AM":"Самую древнюю кожаную обувь, возрастом около 5500 лет, нашли в пещере в Армении. Она была набита травой!","name.AG":"Антигуа и Барбуда","cap.AG":"Сент-Джонс","fam.AG":"365 песчаными пляжами","fact.AG":"На Барбуде живёт одна из крупнейших в мире колоний фрегатов. Самцы раздувают огромные красные горловые мешки, как воздушные шары.","name.AU":"Австралия","cap.AU":"Канберра","fam.AU":"кенгуру","fact.AU":"Большой Барьерный риф — самое крупное сооружение на Земле, созданное живыми существами. Его видно даже из космоса.","name.AT":"Австрия","cap.AT":"Вена","fam.AT":"музыкой Моцарта","fact.AT":"Венский зоопарк Шёнбрунн открылся в 1752 году. Это самый старый из работающих зоопарков мира.","name.AZ":"Азербайджан","cap.AZ":"Баку","fam.AZ":"горящей горой Янардаг","fact.AZ":"В Азербайджане сотни грязевых вулканов — около половины всех на Земле. Они булькают и выплёвывают холодную липкую грязь.","name.BI":"Бурунди","cap.BI":"Гитега","fam.BI":"знаменитыми королевскими барабанщиками","fact.BI":"Королевские барабанщики играют на огромных барабанах и танцуют, а выходят на сцену, неся тяжёлые барабаны на головах!","name.BE":"Бельгия","cap.BE":"Брюссель","fam.BE":"вафлями и шоколадом","fact.BE":"Знаменитых смурфиков и героя комиксов Тинтина придумали в Бельгии — стране, которая обожает комиксы!","name.BJ":"Бенин","cap.BJ":"Котону","fam.BJ":"деревней на озере Ганвье","fact.BJ":"Официальная столица — Порто-Ново, но правительство в основном работает в Котону. А в Ганвье люди живут в домах на сваях прямо в озере!","name.BF":"Буркина-Фасо","cap.BF":"Уагадугу","fam.BF":"кинофестивалем ФЕСПАКО","fact.BF":"Раз в два года здесь проходит ФЕСПАКО — самый большой кинофестиваль Африки, где режиссёры со всего континента показывают свои фильмы.","name.BD":"Бангладеш","cap.BD":"Дакка","fam.BD":"длинным пляжем Кокс-Базара","fact.BD":"Бангладеш делит с соседней Индией Сундарбан — крупнейший в мире мангровый лес. Тигры там отлично плавают и переплывают широкие реки.","name.BG":"Болгария","cap.BG":"София","fam.BG":"розовым маслом и йогуртом","fact.BG":"В Болгарии выращивают столько роз, что она делает огромную часть всего розового масла в мире. Его добавляют в духи повсюду.","name.BH":"Бахрейн","cap.BH":"Манама","fam.BH":"Деревом жизни в пустыне","fact.BH":"Бахрейн состоит из более чем 30 островов, а главный остров соединён с Саудовской Аравией мостом длиной 25 километров.","name.BS":"Багамы","cap.BS":"Нассау","fam.BS":"плавающими свиньями","fact.BS":"Багамы — это около 700 островов и больше 2000 крошечных островков, которые называют кеями. Они разбросаны по прозрачной бирюзовой воде.","name.BA":"Босния и Герцеговина","cap.BA":"Сараево","fam.BA":"Старым мостом в Мостаре","fact.BA":"Каждое лето смелые ныряльщики прыгают со Старого моста в Мостаре в реку с высоты больше 20 метров!","name.BY":"Беларусь","cap.BY":"Минск","fam.BY":"картофельными драниками","fact.BY":"В Беларуси живёт зубр — самое тяжёлое сухопутное животное Европы. Он бродит по древней Беловежской пуще.","name.BZ":"Белиз","cap.BZ":"Бельмопан","fam.BZ":"Большой голубой дырой","fact.BZ":"В Белизе находится первый в мире заповедник ягуаров — тропический лес, созданный, чтобы защищать этих больших пятнистых кошек.","name.BO":"Боливия","cap.BO":"Ла-Пас","fam.BO":"солончаком Уюни","fact.BO":"У Боливии две столицы: Ла-Пас, где работает правительство, и Сукре. Ла-Пас находится на высоте около 3600 метров над морем!","name.BR":"Бразилия","cap.BR":"Бразилиа","fam.BR":"статуей Христа-Искупителя","fact.BR":"Бразилия пять раз выигрывала чемпионат мира по футболу среди мужчин — больше, чем любая другая страна.","name.BB":"Барбадос","cap.BB":"Бриджтаун","fam.BB":"летучими рыбами","fact.BB":"Грейпфрут впервые нашли на Барбадосе в XVIII веке. Это природная смесь помело и сладкого апельсина.","name.BN":"Бруней","cap.BN":"Бандар-Сери-Бегаван","fam.BN":"деревней на воде Кампонг-Айер","fact.BN":"Кампонг-Айер в Брунее — огромная деревня на сваях над рекой. Там есть свои школы, магазины и даже пожарные станции на воде.","name.BT":"Бутан","cap.BT":"Тхимпху","fam.BT":"монастырём Гнездо тигрицы","fact.BT":"Бутан измеряет, насколько счастливы его жители, с помощью «валового национального счастья», а не только считает деньги.","name.BW":"Ботсвана","cap.BW":"Габороне","fam.BW":"дельтой Окаванго","fact.BW":"Река Окаванго никогда не доходит до моря. Она разливается огромной зелёной дельтой посреди пустыни Калахари.","name.CF":"ЦАР","cap.CF":"Банги","fam.CF":"слонами Дзанга-Бай","fact.CF":"В Дзанга-Санга сотни лесных слонов собираются на большой грязной поляне — «бай», чтобы пить воду, богатую минералами.","name.CA":"Канада","cap.CA":"Оттава","fam.CA":"кленовым сиропом","fact.CA":"У Канады самая длинная береговая линия в мире — больше 240 000 km. Если проходить по 20 km в день, путь займёт больше 30 лет!","name.CH":"Швейцария","cap.CH":"Берн","fam.CH":"шоколадом, сыром и часами","fact.CH":"В Швейцарии четыре государственных языка — немецкий, французский, итальянский и ретороманский — и больше 1500 озёр.","name.CL":"Чили","cap.CL":"Сантьяго","fam.CL":"статуями острова Пасхи","fact.CL":"Чили очень длинная и узкая: около 4300 km с севера на юг, но в среднем всего около 175 km в ширину.","name.CN":"Китай","cap.CN":"Пекин","fam.CN":"большими пандами","fact.CN":"Во всём Китае одно время, хотя страна почти такая же широкая, как материковая часть США.","name.CI":"Кот-д’Ивуар","cap.CI":"Ямусукро","fam.CI":"тем, что выращивает больше всех какао","fact.CI":"Здесь выращивают больше какао, чем в любой другой стране, так что твой шоколад вполне мог начаться с местных бобов.","name.CM":"Камерун","cap.CM":"Яунде","fam.CM":"прозвищем «Африка в миниатюре»","fact.CM":"Его называют «Африкой в миниатюре», потому что в одной стране есть пляжи, пустыни, горы, тропические леса и саванны.","name.CD":"ДР Конго","cap.CD":"Киншаса","fam.CD":"бонобо и окапи","fact.CD":"Бонобо и окапи живут на воле только здесь. У окапи полоски как у зебры, но на самом деле это родственник жирафа!","name.CG":"Республика Конго","cap.CG":"Браззавиль","fam.CG":"гориллами парка Одзала-Кокуа","fact.CG":"Больше половины страны покрыто тропическим лесом, где живут западные равнинные гориллы, лесные слоны и шимпанзе.","name.CO":"Колумбия","cap.CO":"Богота","fam.CO":"рекой Каньо-Кристалес","fact.CO":"В Колумбии больше видов птиц, чем в любой другой стране, — больше 1900, от крошечных колибри до огромных кондоров.","name.KM":"Коморы","cap.KM":"Морони","fam.KM":"латимериями и иланг-илангом","fact.KM":"Латимерия — рыба, которая, как думали, вымерла вместе с динозаврами, — до сих пор плавает в глубоких водах у этих островов.","name.CV":"Кабо-Верде","cap.CV":"Прая","fam.CV":"певицей Сезарией Эворой","fact.CV":"На острове Фогу есть огромный вулкан, который всё ещё действует, а люди выращивают виноград и кофе прямо в его гигантском кратере.","name.CR":"Коста-Рика","cap.CR":"Сан-Хосе","fam.CR":"ленивцами и вулканом Ареналь","fact.CR":"Коста-Рика занимает крошечную часть суши Земли, но здесь живёт около 5% всех видов растений и животных мира.","name.CU":"Куба","cap.CU":"Гавана","fam.CU":"старыми машинами 1950-х","fact.CU":"Колибри-пчёлка живёт только на Кубе. Это самая маленькая птица в мире — всего около 5 см в длину.","name.CY":"Кипр","cap.CY":"Никосия","fam.CY":"сыром халлуми","fact.CY":"На Кипре живёт свой дикий баран — муфлон. Он обитает в горных лесах острова и даже изображён на монетах.","name.CZ":"Чехия","cap.CZ":"Прага","fam.CZ":"Карловым мостом","fact.CZ":"Слово «робот» впервые использовал чешский писатель Карел Чапек в пьесе 1920 года. Оно происходит от чешского слова, означающего тяжёлый труд.","name.DE":"Германия","cap.DE":"Берлин","fam.DE":"сказочным замком Нойшванштайн","fact.DE":"Говорят, в Германии больше 3000 видов хлеба, а местные пекари славятся кренделями и ржаными буханками.","name.DJ":"Джибути","cap.DJ":"Джибути","fam.DJ":"солёными берегами озера Ассаль","fact.DJ":"Озеро Ассаль лежит примерно на 155 метров ниже уровня моря — это самая низкая точка Африки, а вода в нём даже солонее, чем в Мёртвом море.","name.DM":"Доминика","cap.DM":"Розо","fam.DM":"Кипящим озером","fact.DM":"Доминику называют Островом природы. Говорят, на ней 365 рек — по одной на каждый день года.","name.DK":"Дания","cap.DK":"Копенгаген","fam.DK":"разноцветными кубиками LEGO","fact.DK":"LEGO придумали в Дании. Название происходит от датских слов leg godt — «играй хорошо».","name.DO":"Доминиканская Республика","cap.DO":"Санто-Доминго","fam.DO":"ларимаром — небесно-голубым камнем","fact.DO":"Из Доминиканской Республики в главную бейсбольную лигу попало больше игроков, чем из любой другой страны, кроме США.","name.DZ":"Алжир","cap.DZ":"Алжир","fam.DZ":"наскальными рисунками Тассилин-Аджер","fact.DZ":"Это самая большая страна Африки, и больше 80 процентов её земли занимает пустыня Сахара.","name.EC":"Эквадор","cap.EC":"Кито","fam.EC":"Галапагосскими островами","fact.EC":"Земля немного выпуклая на экваторе, поэтому вершина горы Чимборасо — точка суши, самая далёкая от центра Земли.","name.EG":"Египет","cap.EG":"Каир","fam.EG":"пирамидами Гизы","fact.EG":"Великая пирамида Гизы была самым высоким зданием, построенным людьми, около 3800 лет — пока её не обогнал собор в Англии.","name.ER":"Эритрея","cap.ER":"Асмэра","fam.ER":"архипелагом Дахлак","fact.ER":"Столица славится яркими старыми зданиями, среди них — заправка в форме самолёта с длинными крыльями.","name.ES":"Испания","cap.ES":"Мадрид","fam.ES":"фламенко и паэльей","fact.ES":"Каждый август в городке Буньоль проходит Томатина — огромный праздник, где тысячи людей кидаются друг в друга помидорами!","name.EE":"Эстония","cap.EE":"Таллин","fam.EE":"тем, что там изобрели Skype","fact.EE":"Около половины Эстонии покрыто лесом, а у её берегов больше 2000 островов.","name.ET":"Эфиопия","cap.ET":"Аддис-Абеба","fam.ET":"тем, что это родина кофе","fact.ET":"Здесь свой календарь с 13 месяцами: Новый год наступает в сентябре, а номер года отстаёт примерно на семь лет!","name.FI":"Финляндия","cap.FI":"Хельсинки","fam.FI":"муми-троллями и саунами","fact.FI":"В Финляндии около 3 миллионов саун — почти по одной сауне на каждых двух жителей!","name.FJ":"Фиджи","cap.FJ":"Сува","fam.FJ":"олимпийским золотом в регби-7","fact.FJ":"Фиджи состоит из более чем 330 островов, но люди живут только примерно на 110 из них.","name.FR":"Франция","cap.FR":"Париж","fam.FR":"Эйфелевой башней","fact.FR":"Благодаря островам по всему миру у Франции больше часовых поясов, чем у любой другой страны, — целых 12!","name.FM":"Микронезия","cap.FM":"Паликир","fam.FM":"каменными руинами Нан-Мадол","fact.FM":"На острове Яп люди использовали как деньги огромные круглые каменные диски. Некоторые выше взрослого человека и такие тяжёлые, что их не сдвинуть!","name.GA":"Габон","cap.GA":"Либревиль","fam.GA":"бегемотами в морских волнах","fact.GA":"На некоторых пляжах можно увидеть бегемотов, плещущихся в океанских волнах, слонов, гуляющих по песку, и китов у берега!","name.GB":"Великобритания","cap.GB":"Лондон","fam.GB":"часовой башней Биг-Бен","fact.GB":"Футбол, регби, теннис и крикет получили свои современные правила в Великобритании, а теперь в них играют по всему миру.","name.GE":"Грузия","cap.GE":"Тбилиси","fam.GE":"сырными хачапури","fact.GE":"У Грузии свой алфавит, один из древнейших среди тех, что используют сегодня. В нём 33 завитые буквы, совсем не похожие на русские.","name.GH":"Гана","cap.GH":"Аккра","fam.GH":"тканью кенте","fact.GH":"Озеро Вольта — самое большое по площади искусственное озеро в мире. Его создали, построив плотину на реке Вольта.","name.GN":"Гвинея","cap.GN":"Конакри","fam.GN":"нагорьем Фута-Джаллон","fact.GN":"Реки Нигер, Сенегал и Гамбия начинаются в её горах, поэтому Гвинею часто называют водонапорной башней Западной Африки.","name.GM":"Гамбия","cap.GM":"Банжул","fam.GM":"прозвищем «Улыбающийся берег Африки»","fact.GM":"Это самая маленькая страна на материковой части Африки — узкая полоска земли вдоль реки, которую с трёх сторон окружает Сенегал.","name.GW":"Гвинея-Бисау","cap.GW":"Бисау","fam.GW":"островами Бижагош","fact.GW":"На островах Бижагош бегемоты плавают в солёной морской воде между островами, а зелёные морские черепахи откладывают яйца на пляжах.","name.GQ":"Экваториальная Гвинея","cap.GQ":"Малабо","fam.GQ":"островом Биоко","fact.GQ":"Это единственная страна в Африке, где испанский — официальный язык, а её столица стоит на острове, а не на материке.","name.GR":"Греция","cap.GR":"Афины","fam.GR":"древними Олимпийскими играми","fact.GR":"Олимпийские игры начались в Древней Греции почти 2800 лет назад, в месте под названием Олимпия.","name.GD":"Гренада","cap.GD":"Сент-Джорджес","fam.GD":"мускатным орехом и пряностями","fact.GD":"На Гренаде есть подводный парк скульптур: статуи на морском дне постепенно становятся домом для кораллов и рыб.","name.GT":"Гватемала","cap.GT":"Гватемала","fam.GT":"городом майя Тикаль","fact.GT":"Национальная птица — кетцаль с длинными блестящими зелёными перьями на хвосте, и деньги страны тоже называются кетцаль!","name.GY":"Гайана","cap.GY":"Джорджтаун","fam.GY":"гигантским водопадом Кайетур","fact.GY":"Гайана — единственная страна в Южной Америке, где официальный язык — английский.","name.HN":"Гондурас","cap.HN":"Тегусигальпа","fam.HN":"руинами майя в Копане","fact.HN":"У побережья лежат острова Ислас-де-ла-Баия рядом со вторым по величине барьерным рифом в мире, где живут китовые акулы и черепахи.","name.HR":"Хорватия","cap.HR":"Загреб","fam.HR":"Плитвицкими озёрами","fact.HR":"Далматинцы — пятнистые собаки из «101 далматинца» — названы в честь Далмации, солнечного края на побережье Хорватии.","name.HT":"Гаити","cap.HT":"Порт-о-Пренс","fam.HT":"крепостью Ла-Ферьер","fact.HT":"Гаити — одна из самых гористых стран Карибского моря. Её название происходит от слова индейцев таино, означающего «земля высоких гор».","name.HU":"Венгрия","cap.HU":"Будапешт","fam.HU":"кубиком Рубика","fact.HU":"Кубик Рубика изобрели в Венгрии в 1974 году, а Будапешт стоит на более чем 100 природных горячих источниках.","name.ID":"Индонезия","cap.ID":"Джакарта","fam.ID":"огромными комодскими варанами","fact.ID":"Индонезия состоит из более чем 17 000 островов и с одного края до другого тянется шире, чем материковая часть США.","name.IN":"Индия","cap.IN":"Нью-Дели","fam.IN":"Тадж-Махалом","fact.IN":"Киноиндустрия Индии, включая Болливуд, снимает за год больше фильмов, чем любая другая страна мира.","name.IE":"Ирландия","cap.IE":"Дублин","fam.IE":"трилистником и лепреконами","fact.IE":"Хеллоуин появился в Ирландии, где когда-то фонари делали, вырезая лица на репе, а не на тыкве!","name.IR":"Иран","cap.IR":"Тегеран","fam.IR":"красивыми персидскими коврами","fact.IR":"Давным-давно в Иране строили яхчалы — огромные ледяные дома в форме купола, где лёд не таял в пустыне всё лето.","name.IQ":"Ирак","cap.IQ":"Багдад","fam.IQ":"древним городом Вавилоном","fact.IQ":"Одну из первых в мире письменностей придумали в древнем Ираке больше 5000 лет назад: на глиняных табличках выдавливали значки в форме клиньев.","name.IS":"Исландия","cap.IS":"Рейкьявик","fam.IS":"гейзерами и вулканами","fact.IS":"В Исландии совсем нет комаров, а летом солнце почти не заходит, так что светло почти всю ночь.","name.IL":"Израиль","cap.IL":"Иерусалим","fam.IL":"крепостью Масада в пустыне","fact.IL":"Мёртвое море на восточной границе Израиля такое солёное, что можно лежать на воде, даже не пытаясь плыть.","name.IT":"Италия","cap.IT":"Рим","fam.IT":"пиццей и Падающей башней","fact.IT":"В Италии больше объектов Всемирного наследия ЮНЕСКО, чем в любой другой стране, — от древних руин до каналов Венеции.","name.JM":"Ямайка","cap.JM":"Кингстон","fam.JM":"музыкой регги","fact.JM":"На Ямайке выросли одни из самых быстрых спринтеров в истории, например Усэйн Болт, рекордсмен мира в беге на 100 м.","name.JO":"Иордания","cap.JO":"Амман","fam.JO":"розово-красным городом Петра","fact.JO":"Песок и скалы в пустыне Вади-Рам в Иордании такие красные, что там снимали фильмы о планете Марс.","name.JP":"Япония","cap.JP":"Токио","fam.JP":"суши и скоростными поездами","fact.JP":"В Японии миллионы торговых автоматов. Они продают холодные напитки, горячий суп, мороженое и даже зонтики.","name.KZ":"Казахстан","cap.KZ":"Астана","fam.KZ":"тем, что это родина яблок","fact.KZ":"Казахстан — самая большая страна в мире, у которой нет выхода к океану. Он больше всей Западной Европы.","name.KE":"Кения","cap.KE":"Найроби","fam.KE":"заповедником Масаи-Мара","fact.KE":"Кенийские бегуны славятся победами в марафонах, а экватор проходит прямо через страну и делит её на север и юг.","name.KG":"Киргизия","cap.KG":"Бишкек","fam.KG":"горным озером Иссык-Куль","fact.KG":"Кочевники в Киргизии живут в круглых шатрах — юртах, а верх юрты даже изображён на флаге страны.","name.KH":"Камбоджа","cap.KH":"Пномпень","fam.KH":"храмом Ангкор-Ват","fact.KH":"В сезон дождей озеро Тонлесап в Камбодже становится в несколько раз больше, а вытекающая из него река поворачивает вспять!","name.KI":"Кирибати","cap.KI":"Южная Тарава","fam.KI":"первым новогодним рассветом","fact.KI":"Кирибати — единственная страна во всех четырёх полушариях: к северу и к югу от экватора и к востоку и к западу от 180-го меридиана.","name.KN":"Сент-Китс и Невис","cap.KN":"Бастер","fam.KN":"крепостью Бримстон-Хилл","fact.KN":"Это самая маленькая страна Америки, и говорят, что зелёных мартышек на островах больше, чем людей!","name.KR":"Южная Корея","cap.KR":"Сеул","fam.KR":"кимчи и музыкой K-pop","fact.KR":"В Южной Корее один из самых быстрых интернетов в мире, а профессиональные киберспортсмены там бывают знамениты, как звёзды спорта.","name.KW":"Кувейт","cap.KW":"Эль-Кувейт","fam.KW":"водонапорными башнями с синими шарами","fact.KW":"В Кувейте совсем нет рек и озёр, поэтому большую часть питьевой воды получают, убирая соль из морской воды.","name.LA":"Лаос","cap.LA":"Вьентьян","fam.LA":"Долиной кувшинов","fact.LA":"У Лаоса нет моря, но через него течёт река Меконг. На ней есть место Сипхандон, что значит «Четыре тысячи островов».","name.LB":"Ливан","cap.LB":"Бейрут","fam.LB":"древними кедрами","fact.LB":"В центре флага Ливана — зелёный кедр. Кедры там могут жить больше 1000 лет!","name.LR":"Либерия","cap.LR":"Монровия","fam.LR":"национальным парком Сапо","fact.LR":"Её флаг очень похож на флаг США, только на нём одна большая белая звезда вместо пятидесяти.","name.LY":"Ливия","cap.LY":"Триполи","fam.LY":"руинами Лептис-Магны","fact.LY":"Больше 90 процентов страны — пустыня, и огромные подземные трубы под названием Великая рукотворная река везут воду в города.","name.LC":"Сент-Люсия","cap.LC":"Кастри","fam.LC":"двумя горами Питон","fact.LC":"На Сент-Люсии возле Суфриера есть вулкан, к которому можно подъехать на машине — прямо к бурлящим грязевым озёрам и горячим источникам.","name.LI":"Лихтенштейн","cap.LI":"Вадуц","fam.LI":"изготовлением зубных протезов","fact.LI":"Эта крошечная страна — одна из двух в мире, у которых нет моря и у всех соседей тоже нет выхода к морю!","name.LK":"Шри-Ланка","cap.LK":"Коломбо","fam.LK":"знаменитым цейлонским чаем","fact.LK":"У этого острова в форме капли две столицы: шумный Коломбо и соседний город Шри-Джаяварденепура-Котте, где заседает парламент.","name.LS":"Лесото","cap.LS":"Масеру","fam.LS":"прозвищем «Королевство в небе»","fact.LS":"Это единственная страна в мире, где вся земля лежит выше 1000 метров над уровнем моря. Поэтому её и называют Королевством в небе.","name.LT":"Литва","cap.LT":"Вильнюс","fam.LT":"Горой крестов","fact.LT":"Баскетбольная сборная Литвы трижды выигрывала олимпийскую бронзу, и этот спорт любят по всей стране.","name.LU":"Люксембург","cap.LU":"Люксембург","fam.LU":"тем, что это единственное великое герцогство","fact.LU":"В 2020 году Люксембург первым в мире сделал все автобусы, трамваи и поезда бесплатными для всех.","name.LV":"Латвия","cap.LV":"Рига","fam.LV":"национальным парком Гауя","fact.LV":"Латвия — одна из самых зелёных стран Европы: больше половины её земли покрыто лесом.","name.MA":"Марокко","cap.MA":"Рабат","fam.MA":"синим городом Шефшауэн","fact.MA":"Университет аль-Карауин в Фесе, основанный в 859 году, часто называют самым старым из работающих университетов мира.","name.MC":"Монако","cap.MC":"Монако","fam.MC":"гонкой «Формулы-1» по улицам города","fact.MC":"Монако — вторая самая маленькая страна в мире. Она такая крошечная, что её можно пересечь пешком меньше чем за час.","name.MD":"Молдавия","cap.MD":"Кишинёв","fam.MD":"огромными подземными винными погребами","fact.MD":"Подземные погреба в Милештий-Мичь — это туннели длиной около 200 km, поэтому гости проезжают по ним на машине!","name.MG":"Мадагаскар","cap.MG":"Антананариву","fam.MG":"лемурами","fact.MG":"Около 90 процентов его растений и животных больше нигде на Земле не живут, включая больше 100 видов лемуров!","name.MV":"Мальдивы","cap.MV":"Мале","fam.MV":"тем, что это самая низкая страна на Земле","fact.MV":"Мальдивы — это около 1200 коралловых островов, а самая высокая природная точка во всей стране поднимается всего примерно на 2,4 метра.","name.MX":"Мексика","cap.MX":"Мехико","fam.MX":"пирамидой Чичен-Ица","fact.MX":"Кукурузу впервые начали выращивать в Мексике около 9000 лет назад, и сегодня её едят в тортильях, тамалес и многих других блюдах.","name.MH":"Маршалловы Острова","cap.MH":"Маджуро","fam.MH":"картами мореходов из палочек","fact.MH":"Страна состоит из 29 коралловых атоллов и 5 островов, и большая часть её земли поднимается над морем всего примерно на 2 метра.","name.MK":"Северная Македония","cap.MK":"Скопье","fam.MK":"старым городом Охрид","fact.MK":"Охридское озеро — одно из древнейших в мире: ему больше миллиона лет, и в нём полно существ, которых больше нигде нет.","name.ML":"Мали","cap.ML":"Бамако","fam.ML":"древним городом Тимбукту","fact.ML":"Большая мечеть Дженне — самое большое здание из глиняного кирпича в мире, и каждый год люди покрывают её свежим слоем глины.","name.MT":"Мальта","cap.MT":"Валлетта","fam.MT":"храмами Джгантия","fact.MT":"Храмам Джгантия на Мальте больше 5000 лет — они старше и Стоунхенджа, и египетских пирамид!","name.MM":"Мьянма","cap.MM":"Нейпьидо","fam.MM":"храмами Багана","fact.MM":"В Мьянме многие наносят на лицо танаку — жёлтую пасту из молотой коры дерева, чтобы не перегреться на солнце.","name.ME":"Черногория","cap.ME":"Подгорица","fam.ME":"Которским заливом","fact.ME":"Название Черногория значит «чёрная гора» — из-за тёмных лесов на горе Ловчен у побережья.","name.MN":"Монголия","cap.MN":"Улан-Батор","fam.MN":"огромной статуей Чингисхана","fact.MN":"В Монголии лошадей больше, чем людей, а дети скачут наперегонки по степи на большом летнем празднике Наадам.","name.MZ":"Мозамбик","cap.MZ":"Мапуту","fam.MZ":"архипелагом Базаруто","fact.MZ":"У островов Базаруто до сих пор плавают дюгони — добрые «морские коровы», а ещё дельфины, черепахи и огромные китовые акулы.","name.MR":"Мавритания","cap.MR":"Нуакшот","fam.MR":"Глазом Сахары","fact.MR":"Глаз Сахары — гигантский каменный круг шириной около 40 km. Он такой большой, что космонавты используют его как ориентир из космоса!","name.MU":"Маврикий","cap.MU":"Порт-Луи","fam.MU":"птицей додо","fact.MU":"Додо была большой нелетающей птицей, которая жила только на этом острове. Сегодня она изображена на гербе страны.","name.MW":"Малави","cap.MW":"Лилонгве","fam.MW":"прозвищем «Тёплое сердце Африки»","fact.MW":"В озере Малави больше видов рыб, чем в любом другом озере мира, и многие из них — яркие разноцветные цихлиды.","name.MY":"Малайзия","cap.MY":"Куала-Лумпур","fam.MY":"башнями-близнецами Петронас","fact.MY":"В лесах Малайзии растёт раффлезия — самый большой цветок в мире. Он бывает шириной с автомобильное колесо и пахнет тухлым мясом!","name.NA":"Намибия","cap.NA":"Виндхук","fam.NA":"красными дюнами Соссусфлей","fact.NA":"Одни из самых высоких песчаных дюн в мире находятся в пустыне Намиб, которую считают самой древней пустыней на Земле.","name.NE":"Нигер","cap.NE":"Ниамей","fam.NE":"жирафами Куре","fact.NE":"Здесь живут последние дикие западноафриканские жирафы. Они свободно бродят возле деревень и полей недалеко от столицы.","name.NG":"Нигерия","cap.NG":"Абуджа","fam.NG":"фильмами Нолливуда","fact.NG":"Здесь живёт больше людей, чем в любой другой стране Африки, а её киноиндустрия Нолливуд снимает тысячи фильмов каждый год.","name.NI":"Никарагуа","cap.NI":"Манагуа","fam.NI":"вулканами-близнецами Ометепе","fact.NI":"Озеро Никарагуа такое огромное, что в нём сотни островов, а тупорылые акулы заплывают в него из моря вверх по реке!","name.NL":"Нидерланды","cap.NL":"Амстердам","fam.NL":"ветряными мельницами и тюльпанами","fact.NL":"Около четверти Нидерландов лежит ниже уровня моря. Сушу защищают дамбы, насосы, а в старину — ветряные мельницы.","name.NO":"Норвегия","cap.NO":"Осло","fam.NO":"глубокими фьордами","fact.NO":"Суши с лососем стали популярны в Японии благодаря Норвегии, которая начала поставлять туда своего лосося в 1980-х.","name.NP":"Непал","cap.NP":"Катманду","fam.NP":"смелыми проводниками-шерпами","fact.NP":"Флаг Непала — единственный государственный флаг в мире, который не прямоугольный. Он похож на два треугольника один над другим.","name.NR":"Науру","cap.NR":"Ярен","fam.NR":"тем, что это самое крошечное островное государство","fact.NR":"Науру такой маленький, что дорога вокруг всего острова длиной всего около 19 km — это примерно 30 минут на машине.","name.NZ":"Новая Зеландия","cap.NZ":"Веллингтон","fam.NZ":"птицами киви","fact.NZ":"В Новой Зеландии нет своих сухопутных змей, и это было одно из последних больших мест на Земле, где поселились люди.","name.OM":"Оман","cap.OM":"Маскат","fam.OM":"деревьями ладана","fact.OM":"В Омане есть карстовая воронка Бимма с сине-зелёной водой, где маленькие рыбки нежно покусывают ноги пловцов.","name.PK":"Пакистан","cap.PK":"Исламабад","fam.PK":"розовой гималайской солью","fact.PK":"В Пакистане пять из 14 гор мира выше 8000 метров, включая K2 — вторую по высоте вершину Земли.","name.PA":"Панама","cap.PA":"Панама","fam.PA":"каналом между двумя океанами","fact.PA":"Корабли в Панамском канале поднимаются примерно на 26 метров с помощью огромных шлюзов — как в лифте из воды.","name.PE":"Перу","cap.PE":"Лима","fam.PE":"руинами Мачу-Пикчу","fact.PE":"В Перу выращивают больше 3000 сортов картофеля, а впервые его начали выращивать в Андах тысячи лет назад.","name.PH":"Филиппины","cap.PH":"Манила","fam.PH":"Шоколадными холмами","fact.PH":"На Филиппинах живёт долгопят — крошечный зверёк с огромными глазами. Каждый глаз размером почти с весь его мозг!","name.PW":"Палау","cap.PW":"Нгерулмуд","fam.PW":"купанием в Озере медуз","fact.PW":"Гостям Палау ставят в паспорт штамп с обещанием беречь природу и морскую жизнь островов.","name.PG":"Папуа — Новая Гвинея","cap.PG":"Порт-Морсби","fam.PG":"райскими птицами","fact.PG":"В Папуа — Новой Гвинее говорят больше чем на 800 языках — больше, чем в любой другой стране мира.","name.PL":"Польша","cap.PL":"Варшава","fam.PL":"пирогами-варениками","fact.PL":"Мария Кюри, первая женщина, получившая Нобелевскую премию, родилась в Варшаве в 1867 году.","name.KP":"Северная Корея","cap.KP":"Пхеньян","fam.KP":"огромной гостиницей в форме пирамиды","fact.KP":"Гора Пэктусан — самая высокая на Корейском полуострове. Это старый вулкан с озером в кратере, которое называют Небесным озером.","name.PT":"Португалия","cap.PT":"Лиссабон","fam.PT":"пирожными паштел-де-ната","fact.PT":"Португалия даёт около половины всей пробки в мире — коры пробкового дуба, из которой делают пробки для бутылок и доски.","name.PY":"Парагвай","cap.PY":"Асунсьон","fam.PY":"кружевом ньяндути, похожим на паутину","fact.PY":"Большинство жителей Парагвая говорят на гуарани — местном языке Южной Америки — и на испанском. Оба языка официальные.","name.PS":"Палестина","cap.PS":"Рамалла","fam.PS":"древним городом Иерихоном","fact.PS":"Иерихон — один из древнейших городов мира. Люди живут там больше 10 000 лет, гораздо ниже уровня моря.","name.QA":"Катар","cap.QA":"Доха","fam.QA":"чемпионатом мира по футболу 2022 года","fact.QA":"В Катаре есть внутреннее море Хор-эль-Удейд, где огромные песчаные дюны спускаются прямо к воде.","name.RO":"Румыния","cap.RO":"Бухарест","fam.RO":"замками Трансильвании","fact.RO":"В Карпатах Румынии живёт больше бурых медведей, чем в любой другой европейской стране, кроме России.","name.RU":"Россия","cap.RU":"Москва","fam.RU":"матрёшками","fact.RU":"Россия такая широкая, что в ней 11 часовых поясов, а её озеро Байкал — самое глубокое на Земле.","name.RW":"Руанда","cap.RW":"Кигали","fam.RW":"прозвищем «Страна тысячи холмов»","fact.RW":"Пластиковые пакеты здесь запрещены, а в одну субботу каждого месяца люди вместе убирают свои районы, поэтому улицы такие чистые.","name.SA":"Саудовская Аравия","cap.SA":"Эр-Рияд","fam.SA":"пустыней Руб-эль-Хали","fact.SA":"Саудовская Аравия — одна из самых больших стран без постоянных рек, поэтому она получает много пресной воды из морской.","name.SD":"Судан","cap.SD":"Хартум","fam.SD":"тем, что пирамид там больше, чем в Египте","fact.SD":"Здесь больше древних пирамид, чем в Египте, — около 200. Их давным-давно построили цари и царицы Куша.","name.SN":"Сенегал","cap.SN":"Дакар","fam.SN":"Розовым озером Ретба","fact.SN":"Озеро Ретба ярко-розовое из-за крошечных водорослей в очень солёной воде, а люди вручную собирают соль со дна.","name.SG":"Сингапур","cap.SG":"Сингапур","fam.SG":"статуей Мерлиона","fact.SG":"Сингапур — город-государство: вся страна — это один город. Он стал больше, насыпав новую землю вдоль своего берега.","name.SB":"Соломоновы Острова","cap.SB":"Хониара","fam.SB":"огромной лагуной Марово","fact.SB":"Здесь по традиции использовали как деньги нити из крошечных бусин-ракушек, и ракушечные деньги до сих пор нужны на особых праздниках.","name.SL":"Сьерра-Леоне","cap.SL":"Фритаун","fam.SL":"заповедником шимпанзе Такугама","fact.SL":"На острове Тиваи живут карликовые бегемоты и одиннадцать видов приматов, включая шимпанзе и обезьян колобусов.","name.SV":"Сальвадор","cap.SV":"Сан-Сальвадор","fam.SV":"пупусами — кукурузными лепёшками с начинкой","fact.SV":"Сальвадор — самая маленькая страна Центральной Америки, но в нём больше 20 вулканов, поэтому его называют Страной вулканов.","name.SM":"Сан-Марино","cap.SM":"Сан-Марино","fam.SM":"тремя башнями на горе Титано","fact.SM":"Сан-Марино — одна из старейших республик в мире. Говорят, её основали ещё в 301 году.","name.SO":"Сомали","cap.SO":"Могадишо","fam.SO":"самым длинным побережьем материковой Африки","fact.SO":"У Сомали самая длинная береговая линия среди стран материковой Африки, а пастухи разводят миллионы верблюдов ради молока.","name.RS":"Сербия","cap.RS":"Белград","fam.RS":"тоннами малины","fact.RS":"Сербия выращивает столько малины, что входит в число крупнейших производителей малины во всём мире.","name.SS":"Южный Судан","cap.SS":"Джуба","fam.SS":"Суддом — гигантским болотом","fact.SS":"Судд — одно из самых больших болот в мире, а огромные стада белоухих коб каждый год кочуют по этой земле.","name.ST":"Сан-Томе и Принсипи","cap.ST":"Сан-Томе","fam.ST":"скалой-шпилем Пику-Кан-Гранди","fact.ST":"Экватор проходит прямо через крошечный здешний островок Ролаш, где знак показывает границу между севером и югом.","name.SR":"Суринам","cap.SR":"Парамарибо","fam.SR":"тем, что это Амазония, где говорят по-нидерландски","fact.SR":"Около 90% Суринама покрыто тропическим лесом — это одна из самых зелёных и лесистых стран на Земле.","name.SK":"Словакия","cap.SK":"Братислава","fam.SK":"огромным Спишским замком","fact.SK":"Словакия выпускает больше машин на каждого жителя, чем любая другая страна мира!","name.SI":"Словения","cap.SI":"Любляна","fam.SI":"островом на озере Блед","fact.SI":"В Постойнской пещере в Словении живёт протей — слепая розовая саламандра, которая может прожить больше 100 лет!","name.SE":"Швеция","cap.SE":"Стокгольм","fam.SE":"мебелью в плоских коробках и группой ABBA","fact.SE":"В Швеции есть Ледяной отель, который каждую зиму строят заново из снега и льда соседней реки Турнеэльв.","name.SZ":"Эсватини","cap.SZ":"Мбабане","fam.SZ":"Танцем тростника Умхланга","fact.SZ":"В Мбабане работает правительство, а Лобамба — королевская столица. Каждый год тысячи девушек несут высокие стебли тростника на Танце тростника.","name.SC":"Сейшельские Острова","cap.SC":"Виктория","fam.SC":"гигантским орехом коко-де-мер","fact.SC":"Пальма коко-де-мер даёт самое большое семя среди всех растений Земли, и одно такое семя может весить до 25 килограммов!","name.SY":"Сирия","cap.SY":"Дамаск","fam.SY":"замком Крак-де-Шевалье","fact.SY":"Знаменитое сирийское алеппское мыло делают из оливкового и лаврового масла, и его варят уже сотни лет.","name.TD":"Чад","cap.TD":"Нджамена","fam.TD":"каменными арками Эннеди","fact.TD":"В пустыне Эннеди есть огромные природные каменные арки, а в нескольких скрытых озёрцах до сих пор живут редкие пустынные крокодилы.","name.TG":"Того","cap.TG":"Ломе","fam.TG":"глиняными домами Кутаммаку","fact.TG":"В Кутаммаку люди строят высокие глиняные дома, похожие на маленькие замки, с башенками наверху для хранения зерна.","name.TH":"Таиланд","cap.TH":"Бангкок","fam.TH":"тук-туками и плавучими рынками","fact.TH":"В Таиланде живёт свиноносая летучая мышь — одно из самых маленьких млекопитающих Земли. Она весит примерно как канцелярская скрепка.","name.TJ":"Таджикистан","cap.TJ":"Душанбе","fam.TJ":"высокими горами Памира","fact.TJ":"Больше 90 процентов Таджикистана покрыто горами, а около половины страны лежит выше 3000 метров.","name.TM":"Туркмения","cap.TM":"Ашхабад","fam.TM":"огненным кратером Дарваза","fact.TM":"Шерсть ахалтекинских лошадей Туркмении блестит, как начищенный металл, поэтому их часто называют золотыми конями.","name.TL":"Восточный Тимор","cap.TL":"Дили","fam.TL":"коралловыми рифами Атауро","fact.TL":"Слово «Тимор» происходит от малайского слова «восток», а «лесте» по-португальски тоже «восток». Так что название страны значит «Восток Восток»!","name.TO":"Тонга","cap.TO":"Нукуалофа","fam.TO":"каменной аркой Хаамонга","fact.TO":"Горбатые киты каждый год проплывают тысячи километров к тёплым водам Тонга, чтобы родить детёнышей.","name.TT":"Тринидад и Тобаго","cap.TT":"Порт-оф-Спейн","fam.TT":"стальными барабанами стилпэн","fact.TT":"Смоляное озеро Пич-Лейк на Тринидаде — самое большое природное асфальтовое озеро в мире, и по некоторым его частям можно даже ходить.","name.TN":"Тунис","cap.TN":"Тунис","fam.TN":"пустынными декорациями «Звёздных войн»","fact.TN":"Здесь снимали части «Звёздных войн», а город Татавин дал имя родной планете Люка Скайуокера — Татуину.","name.TR":"Турция","cap.TR":"Анкара","fam.TR":"скалами Каппадокии","fact.TR":"Стамбул, самый большой город Турции, стоит сразу на двух континентах — в Европе и Азии, а между ними морской пролив.","name.TV":"Тувалу","cap.TV":"Фунафути","fam.TV":"интернет-адресом .tv","fact.TV":"Тувалу — одна из самых маленьких стран на Земле, а её самая высокая точка поднимается над морем всего примерно на 4,6 метра.","name.TZ":"Танзания","cap.TZ":"Додома","fam.TZ":"горой Килиманджаро","fact.TZ":"Килиманджаро — самая высокая гора Африки, 5895 метров, и самая высокая в мире гора, которая стоит отдельно, а не в горной цепи.","name.UG":"Уганда","cap.UG":"Кампала","fam.UG":"истоком Нила у Джинджи","fact.UG":"Из озера Виктория, самого большого в Африке, Белый Нил начинает долгий путь на север к Средиземному морю.","name.UA":"Украина","cap.UA":"Киев","fam.UA":"золотыми полями подсолнухов","fact.UA":"Станция «Арсенальная» в Киеве — одна из самых глубоких станций метро в мире: около 105 метров под землёй.","name.UY":"Уругвай","cap.UY":"Монтевидео","fam.UY":"гигантской рукой на пляже","fact.UY":"Уругвай выиграл самый первый чемпионат мира по футболу в 1930 году, который сам и принимал, обыграв в финале Аргентину.","name.US":"США","cap.US":"Вашингтон","fam.US":"статуей Свободы","fact.US":"Йеллоустон, созданный в 1872 году, стал первым национальным парком в мире. В нём больше 500 гейзеров, которые выбрасывают горячую воду.","name.UZ":"Узбекистан","cap.UZ":"Ташкент","fam.UZ":"голубыми куполами Самарканда","fact.UZ":"Узбекистан — одна из двух стран, которым, чтобы добраться до океана, нужно пересечь как минимум две другие страны.","name.VA":"Ватикан","cap.VA":"Ватикан","fam.VA":"Сикстинской капеллой","fact.VA":"Ватикан — самая маленькая страна в мире. Он такой крошечный, что целиком находится внутри города Рима!","name.VC":"Сент-Винсент и Гренадины","cap.VC":"Кингстаун","fam.VC":"пиратскими декорациями в бухте Валлилабу","fact.VC":"Сент-винсентский амазон — большой яркий попугай, который больше нигде на Земле не живёт, — национальная птица этих островов.","name.VE":"Венесуэла","cap.VE":"Каракас","fam.VE":"самым высоким водопадом в мире","fact.VE":"Над озером Маракайбо беззвучные молнии сверкают в небе примерно 260 ночей в году — чаще, чем почти где-либо ещё на Земле.","name.VN":"Вьетнам","cap.VN":"Ханой","fam.VN":"островами бухты Халонг","fact.VN":"Шондонг во Вьетнаме — самая большая пещера в мире. Она такая огромная, что внутри у неё своя река, джунгли и даже облака!","name.VU":"Вануату","cap.VU":"Порт-Вила","fam.VU":"прыжками с высоких башен","fact.VU":"В Вануату есть подводная почта: ныряльщики отправляют оттуда непромокаемые открытки прямо со дна моря.","name.WS":"Самоа","cap.WS":"Апиа","fam.WS":"океанской впадиной То-Суа","fact.WS":"В 2011 году Самоа пропустило целый день, 30 декабря: страна перешла на другую сторону линии перемены дат, чтобы календарь совпадал с австралийским.","name.YE":"Йемен","cap.YE":"Сана","fam.YE":"драконовыми деревьями","fact.YE":"Старый город Шибам в Йемене полон высоких домов-башен из глиняного кирпича, поэтому его называют Манхэттеном пустыни.","name.ZA":"ЮАР","cap.ZA":"Претория","fam.ZA":"Столовой горой","fact.ZA":"У ЮАР три столицы: Претория для правительства, Кейптаун для парламента и Блумфонтейн для высших судов.","name.ZM":"Замбия","cap.ZM":"Лусака","fam.ZM":"перелётом летучих мышей в Касанке","fact.ZM":"Каждый год около 10 миллионов крыланов прилетают в национальный парк Касанка. Это самая большая миграция млекопитающих на Земле!","name.ZW":"Зимбабве","cap.ZW":"Хараре","fam.ZW":"огромными стадами слонов в Хванге","fact.ZW":"Водопад Виктория местные жители называют «гремящим дымом», потому что его брызги видно за много километров.","Hint":"Подсказка","Two wrong answers are gone!":"Два неверных ответа исчезли!","It is in {region}.":"Эта страна находится здесь: {region}.","It is an island country, in {region}.":"Это островная страна. Где? {region}.","It is next to {name}.":"Она граничит с этой страной: {name}.","It is inside the yellow circle!":"Она внутри жёлтого круга!","Culture finds":"Находки культуры","Press Quiz me to discover more about {name}!":"Нажми «Викторина», чтобы узнать больше: {name}!","Culture finds: {n} of {all}":"Находки культуры: {n} из {all}","Every time you get a country right, our paper plane flies there and paints it with its flag. Get it right 3 times and it lights up in full colour!":"Каждый раз, когда ты угадываешь страну, наш бумажный самолётик летит туда и раскрашивает её флагом. Угадай её 3 раза — и она засияет всеми цветами!","Pick a game below, or tap any country on the globe to open its file and discover its culture. Ready for take-off?":"Выбери игру внизу или нажми на любую страну на глобусе, чтобы открыть её карточку и узнать о её культуре. Готов к взлёту?","Food":"Еда","Celebrations":"Праздники","Arts":"Искусство","Words":"Слова","Nature":"Природа","Everyday life":"Повседневная жизнь","Culture quest":"Культурный квест","Food, festivals, music and more":"Еда, праздники, музыка и не только","Not quite! The answer is {answer}.":"Не совсем! Правильный ответ: {answer}."},"trivia":{}};
